<script setup lang="ts">
const colorMode = useColorMode()
const { data: settings } = await useFetch('/api/settings')
const saving = ref(false)
async function save() { if(!settings.value)return; saving.value=true; try { await $fetch('/api/settings',{method:'PATCH',body:settings.value}); colorMode.preference=settings.value.theme } finally { saving.value=false } }
</script>
<template><div class="mx-auto max-w-3xl px-5 py-8 md:px-10"><h1 class="font-display mb-8 flex items-center gap-3 text-3xl"><UIcon name="i-lucide-settings-2" class="text-[var(--color-accent)]"/>Налаштування</h1><section v-if="settings" class="glass-panel space-y-6 p-6"><label class="block"><span class="mb-2 block text-sm text-secondary">Тема</span><select v-model="settings.theme" class="w-full rounded-xl border border-[var(--color-panel-border)] bg-transparent p-3"><option value="system">Системна</option><option value="light">Світла</option><option value="dark">Темна</option></select></label><label class="block"><span class="mb-2 block text-sm text-secondary">Мова</span><select v-model="settings.locale" class="w-full rounded-xl border border-[var(--color-panel-border)] bg-transparent p-3"><option value="uk">Українська</option><option value="en">English</option></select></label><label class="flex items-center justify-between"><span>Сповіщення</span><input v-model="settings.notifications" type="checkbox" class="size-5 accent-[var(--color-accent)]"></label><div class="flex flex-wrap gap-3"><UButton :loading="saving" @click="save">Зберегти</UButton><a href="/api/export?format=json" class="rounded-lg border border-[var(--color-panel-border)] px-4 py-2 text-sm">Експорт JSON</a><a href="/api/export?format=csv" class="rounded-lg border border-[var(--color-panel-border)] px-4 py-2 text-sm">Експорт CSV</a></div></section></div></template>
